export async function startServer({ cwd, env = {} }) {
  const handle = spawnServer({ cwd, env: { PORT: '0', ...env } });
  const port = await new Promise((resolve, reject) => {
    const onData = () => {
      const match = LISTEN_RE.exec(handle.stdout());
      if (match) resolve(Number(match[1]));
    };
    handle.child.stdout.on('data', onData);
    handle.exited.then(({ code }) =>
      reject(new Error(`server exited (${code}) before listening: ${handle.stderr()}`)),
    );
  });
  const stop = async () => {
    if (handle.child.exitCode === null && handle.child.signalCode === null) {
      handle.child.kill();
    }
    await handle.exited;
  };
  return { ...handle, port, stop };
}

